// The heading at the top of the sidebar, naming the town(s) the map is showing and their state -- from the place points in the map's own tiles and state boundaries shipped with the page (cached by sw.js), so it works offline. Useful on a printout especially, where there's no search box or URL to say where it is.

// generated by ptps_wildfire_demo/us_states.py
export const US_STATES_URL = new URL("../us-states.geojson", import.meta.url);

// kinds of places worth naming, most important first -- not neighborhoods/suburbs, which would crowd out the town itself
// https://openmaptiles.org/schema/#place
const PLACE_CLASSES = ["city", "town", "village", "hamlet"];
// most places to list when several are in view
const MAX_PLACES = 3;

// whether [lng, lat] is inside a polygon, given as rings of [lng, lat] -- by counting how many ring edges a ray from the point crosses, so holes (odd crossings of an inner ring) work too
const inPolygon = ([x, y], rings) => {
  let inside = false;
  for (const ring of rings) {
    for (let i = 0, j = ring.length - 1; i < ring.length; j = i++) {
      const [xi, yi] = ring[i];
      const [xj, yj] = ring[j];
      if (yi > y !== yj > y && x < ((xj - xi) * (y - yi)) / (yj - yi) + xi) {
        inside = !inside;
      }
    }
  }
  return inside;
};

// the name of the state [lng, lat] is in, given the states as a GeoJSON FeatureCollection, or undefined if it's in none of them. The Census' boundaries are generalized, so a place within a kilometer or so of a state line could come back as the neighboring state.
export const stateAt = ({ features }, lngLat) =>
  features.find(({ geometry: { type, coordinates } }) =>
    (type === "Polygon" ? [coordinates] : coordinates).some((rings) =>
      inPolygon(lngLat, rings),
    ),
  )?.properties.name;

// "Gold Hill, Salina, Colorado" -- or, for places in different states, each with its own: "Fort Collins, Colorado; Cheyenne, Wyoming"
const withStates = (places, stateOf) => {
  const states = places.map(stateOf);
  if (new Set(states).size > 1) {
    return places
      .map((p, i) => [p.name, states[i]].filter(Boolean).join(", "))
      .join("; ");
  }
  return [...places.map((p) => p.name), states[0]].filter(Boolean).join(", ");
};

// Given places as { name, class, rank, x, y } (x/y in screen pixels), the viewport's { width, height }, and a function giving a place's state, returns the heading: the most important places in view, or the nearest one as "Near …" if none are, followed by their state -- or "" if there are none at all.
export const placeHeading = (places, { width, height }, stateOf) => {
  const importance = (p) => [PLACE_CLASSES.indexOf(p.class), p.rank ?? 0];
  const byImportance = (a, b) => {
    const [ca, ra] = importance(a);
    const [cb, rb] = importance(b);
    return ca - cb || ra - rb;
  };
  const named = places.filter((p) => p.name && PLACE_CLASSES.includes(p.class));
  const inView = named.filter(
    (p) => p.x >= 0 && p.x <= width && p.y >= 0 && p.y <= height,
  );
  if (inView.length) {
    // one per name -- a place near a tile edge can come back from more than one tile
    const unique = inView
      .sort(byImportance)
      .filter(
        (p, i, sorted) => sorted.findIndex((q) => q.name === p.name) === i,
      );
    return withStates(unique.slice(0, MAX_PLACES), stateOf);
  }
  const center = { x: width / 2, y: height / 2 };
  const distance = (p) => Math.hypot(p.x - center.x, p.y - center.y);
  const nearest = named.sort((a, b) => distance(a) - distance(b))[0];
  return nearest ? `Near ${withStates([nearest], stateOf)}` : "";
};

// keeps the sidebar heading up to date as the map moves. Only looks at the tiles the map has loaded (roughly what's on screen), so zoomed in on a remote road with no place nearby, the heading is just left off.
export const bindPlaceHeading = (map) => {
  const heading = document.getElementById("map-places");
  // filled in once loaded -- until then (or if it fails), the heading is just the town names
  let states;
  const update = () => {
    const places = map
      .querySourceFeatures("roadsSource", { sourceLayer: "place" })
      .filter(({ geometry }) => geometry.type === "Point")
      .map(({ properties, geometry }) => ({
        name: properties.name,
        class: properties.class,
        rank: properties.rank,
        lngLat: geometry.coordinates,
        ...map.project(geometry.coordinates),
      }));
    const canvas = map.getCanvas();
    const text = placeHeading(
      places,
      { width: canvas.clientWidth, height: canvas.clientHeight },
      (p) => states && stateAt(states, p.lngLat),
    );
    heading.textContent = text;
    heading.hidden = !text;
  };
  map.on("idle", update);
  fetch(US_STATES_URL)
    .then((response) => response.json())
    .then((geojson) => {
      states = geojson;
      update();
    })
    .catch((error) => console.error("couldn't load state boundaries", error));
};
